INSERT INTO `txva_postmeta` VALUES (37621,21856,'_elementor_data','[{\"id\":\"5716c0ec\",\"elType\":\"container\",\"settings\":[],\"elements\":[{\"id\":\"3709e15b\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<!-- wp:paragraph -->\\n<p>Entdeckt die Welt des emotionalen Fesselns.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Wir laden Euch ein zu einer fesselnden Begegnung: In diesem Kurs bieten wir ein Switch-Konzept f\\u00fcr das gemeinsame Entdecken der Seile. Wir schnuppern in das Fesseln und Gefesselt-Werden hinein. Dabei k\\u00f6nnen beide Seilpartner jeweils beide Rollen ausprobieren und sp\\u00fcren, wie sich das Fesseln und Gefesselt-Werden anf\\u00fchlt.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p><strong>Weitere Infos:<\\/strong><\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Als Fesselkleidung eignet sich bequeme, aber enganliegende Kleidung. Ob ihr dabei kurze Shirts \\/ Hosen anziehen wollt oder lieber lange Klamotten tragen wollt, ist euch \\u00fcberlassen. Verzichtet bitte auf allzu rutschige Stoffe (z.B. Leggins aus Polyester), da dies das Fesseln unn\\u00f6tig erschwert.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Bitte bringt euch eine Decke, einen Pulli und dicke Socken zum Dr\\u00fcberziehen und Warmhalten mit.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Leihseile werden f\\u00fcr alle gestellt. Falls ihr selbst bereits Seile habt und diese nutzen m\\u00f6chtet, bringt sie gerne mit.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Eine Anmeldung ist nur paarweise m\\u00f6glich. Voraussetzungen f\\u00fcr diesen Kurs gibt es keine.<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p><strong>Organisatorisches<\\/strong><\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Kursgeb\\u00fchr: 150\\u20ac pro Paar<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Dauer: 3,5 Stunden<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Zeit: Ankunft 10:45 \\u2013 11:00 Uhr <\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Kurs 11:00 \\u2013 15:00 Uhr<\\/p>\\n<!-- \\/wp:paragraph -->\\n\\n<!-- wp:paragraph -->\\n<p>Ort: Spiritual Touch, Olschewskibogen 12, 80935 M\\u00fcnchen<\\/p>\\n<!-- \\/wp:paragraph -->\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}]'),(37622,21856,'_elementor_conditions','a:0:{}'),(37623,21856,'_edit_last','1'),(37624,21856,'_wp_old_slug','schnupperkurs-shibari-2'),(37625,21856,'_yoast_post_redirect_info','a:4:{s:6:\"origin\";s:37:\"veranstaltung/schnupperkurs-shibari-2\";s:6:\"target\";s:79:\"veranstaltung/schnupperkurs-shibari-muenchen-einfuehrung-ins-emotionale-fesseln\";s:4:\"type\";i:301;s:6:\"format\";s:5:\"plain\";}'),(37626,21856,'_yoast_wpseo_metadesc','Erlebt die Kunst des Shibari in München! In unserem Schnupperkurs entdeckt ihr gemeinsam das emotionale Fesseln und Gefesselt-Werden. Keine Vorkenntnisse nötig – jetzt als Paar anmelden!'),(37652,21856,'_wp_page_template','default'),(37666,21856,'_elementor_edit_mode',''),(37667,21869,'_wp_attached_file','2024/09/HeartCircle-Main-neu.png'),(37668,21869,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:1080;s:6:\"height\";i:1080;s:4:\"file\";s:32:\"2024/09/HeartCircle-Main-neu.png\";s:8:\"filesize\";i:1033203;s:5:\"sizes\";a:7:{s:6:\"medium\";a:5:{s:4:\"file\";s:34:\"HeartCircle-Main-neu-1000x1000.png\";s:5:\"width\";i:1000;s:6:\"height\";i:1000;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\";i:859735;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:32:\"HeartCircle-Main-neu-150x150.png\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\";i:41109;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:32:\"HeartCircle-Main-neu-768x768.png\";s:5:\"width\";i:768;s:6:\"height\";i:768;s:9:\"mime-type\";s:9:\"image/png\";s:8:\"filesize\";i:583433;}s:21:\"woocommerce_thumbnail\";a:6:{s:4:\"file\";s:32:\"HeartCir