 !important;color:var(--clay) !important;font-weight:600 !important;margin-bottom:6px !important;display:block !important;}\\r\\n.st-h1{font-size:26px !important;font-weight:600 !important;letter-spacing:-.3px !important;margin-bottom:8px !important;display:block !important;}\\r\\n.st-lead{color:var(--soft) !important;font-size:15px !important;margin-bottom:28px !important;display:block !important;}\\r\\n.st-section{font-size:11px !important;letter-spacing:1.5px !important;text-transform:uppercase !important;color:var(--soft) !important;margin-bottom:14px !important;display:block !important;}\\r\\n\\r\\n\\/* \\u2500\\u2500 PIN \\u2500\\u2500 *\\/\\r\\n.st-dots{display:flex !important;gap:16px !important;justify-content:center !important;margin:30px 0 36px !important;}\\r\\n.st-dot{width:15px !important;height:15px !important;border-radius:50% !important;border:2px solid var(--clay) !important;transition:.18s !important;display:block !important;}\\r\\n.st-dot.on{background:var(--clay) !important;transform:scale(1.12) !important;}\\r\\n.st-dot.err{border-color:var(--danger) !important;}\\r\\n.st-keypad{display:grid !important;grid-template-columns:repeat(3,1fr) !important;gap:12px !important;max-width:300px !important;margin:0 auto !important;}\\r\\n.st-pin-err{color:var(--danger) !important;font-size:13.5px !important;text-align:center !important;margin-top:16px !important;min-height:20px !important;display:block !important;}\\r\\n\\r\\n\\/* \\u2500\\u2500 LIST \\u2500\\u2500 *\\/\\r\\n.st-topbar{display:flex !important;justify-content:space-between !important;align-items:baseline !important;margin-bottom:24px !important;}\\r\\n.st-hello{font-size:23px !important;font-weight:600 !important;}\\r\\n#st button.st-logout{\\r\\n  font-size:14px !important;color:var(--soft) !important;\\r\\n  text-decoration:underline !important;text-underline-offset:3px !important;\\r\\n  background:none !important;padding:0 !important;display:inline !important;\\r\\n}\\r\\n.st-card{background:var(--card) !important;border-radius:var(--r) !important;padding:16px 18px !important;margin-bottom:12px !important;border:1px solid var(--line) !important;display:block !important;}\\r\\n.st-card-date{font-size:14px !important;font-weight:600 !important;margin-bottom:2px !important;display:block !important;}\\r\\n.st-card-time{font-size:20px !important;font-weight:600 !important;color:var(--clay-d) !important;margin:3px 0 8px !important;display:block !important;}\\r\\n.st-card-bar{height:5px !important;border-radius:3px !important;background:linear-gradient(90deg,var(--clay),#D08A6E) !important;opacity:.35 !important;margin-bottom:12px !important;display:block !important;}\\r\\n.st-card-act{display:flex !important;gap:20px !important;padding-top:11px !important;border-top:1px solid var(--line) !important;}\\r\\n#st button.st-edit{color:var(--sage) !important;font-size:14px !important;font-weight:500 !important;display:inline !important;}\\r\\n#st button.st-del{color:var(--danger) !important;font-size:14px !important;font-weight:500 !important;display:inline !important;}\\r\\n.st-empty{color:var(--soft) !important;font-size:14px !important;text-align:center !important;padding:28px 0 !important;display:block !important;}\\r\\n#st button.st-add{\\r\\n  display:block !important;width:100% !important;margin-top:20px !important;\\r\\n  padding:17px !important;border-radius:var(--r) !important;\\r\\n  background:var(--clay) !important;color:#fff !important;\\r\\n  font-size:16px !important;font-weight:600 !important;text-align:center !important;\\r\\n  box-shadow:0 3px 0 var(--clay-d) !important;transition:.1s !important;\\r\\n}\\r\\n#st button.st-add:active{transform:translateY(3px) !important;box-shadow:none !important;}\\r\\n\\r\\n\\/* \\u2500\\u2500 FORM \\u2500\\u2500 *\\/\\r\\n#st button.st-back{\\r\\n  color:var(--soft) !important;font-size:15px !important;\\r\\n  margin-bottom:20px !important;display:block !important;\\r\\n}\\r\\n.st-field{margin-bottom:18px !important;display:block !important;}\\r\\n.st-field label{display:block !important;font-size:13.5px !important;font-weight:600 !important;margin-bottom:7px !important;}\\r\\n#st input.st-input{\\r\\n  display:block !important;width:100% !important;\\r\\n  padding:14px 15px !important;\\r\\n  border:1.5px solid var(--line) !important;border-radius:14px !important;\\r\\n  background:var(--card) !important;font-size:16px !important;color:var(--plum) !important;\\r\\n}\\r\\n#st input.st-input:focus{border-color:var(--clay) !important;outline:none !important;}\\r\\n.st-row{display:flex !important;gap:11px !important;}\\r\\n.st-row .st-field{flex:1 !important;}\\r\\n\\r\\n\\/* Warnboxen *\\/\\r\\n.st-warn,.st-err{display:none !important;border-radius:14px !important;padding:13px 15px !important;margin-bottom:18px !important;gap:11px !important;align-items:flex-start !important;}\\r\\n.st-warn.on{display:flex !important;background:var(--warn-bg) !important;border:1.5px solid #E4A84E !important;}\\r\\n.st-err.on{display:flex !important;background:var(--danger-bg) !important;border:1.5px solid #D9897E !important;}\\r\\n.st-warn-ico,.st-err-ico{font-size:18px !important;flex-shrink:0 !important;}\\r\\n.st-warn-txt{font-size:13.5px !important;color:var(--plum) !important;}\\r\\n.st-warn-txt b{color:var(--warn) !important;font-weight:600 !important;}\\r\\n.st-warn-sub{font-size:12.5px !important;color:var(--soft) !important;margin-top:3px !important;display:block !important;}\\r\\n.st-err-txt{font-size:13.5px !important;color:var(--danger) !important;}\\r\\n.st-err-txt b{font-weight:600 !important;}\\r\\n\\r\\n#st button.st-save{\\r\\n  display:block !important;width:100% !important;padding:17px !important;margin-top:26px !important;\\r\\n  border-radius:var(--r) !important;background:var(--clay) !important;color:#fff !important;\\r\\n  font-size:16px !important;font-weight:600 !important;text-align:center !important;\\r\\n  box-shadow:0 3px 0 var(--clay-d) !important;transition:.1s !important;\\r\\n}\\r\\n#st button.st-save:disabled{background:#C9B5AC !important;box-shadow:none !important;cursor:not-allowed !important;}\\r\\n#st button.st-save:not(:disabled):active{transform:translateY(3px) !important;box-shadow:none !important;}\\r\\n#st button.st-cancel{\\r\\n  display:block !important;width:100% !important;padding:14px !important;margin-top:10px !important;\\r\\n  border-radius:var(--r) !important;border:1.5px solid var(--line) !important;\\r\\n  background:transparent !important;color:var(--soft) !important;\\r\\n  font-size:15px !important;text-align:center !important;\\r\\n}\\r\\n\\r\\n\\/* \\u2500\\u2500 DELETE OVERLAY \\u2500\\u2500 *\\/\\r\\n.st-overlay{display:none;position:fixed !important;inset:0 !important;background:rgba(62,42,52,.5) !important;z-index:9999 !important;justify-content:flex-end !important;flex-direction:column !important;padding:20px !important;}\\r\\n.st-overlay.on{display:flex !important;}\\r\\n.st-sheet{background:var(--card) !important;border-radius:22px !important;padding:24px 20px !important;}\\r\\n.st-sheet-title{font-size:18px !important;font-weight:600 !important;margin-bottom:6px !important;display:block !important;}\\r\\n.st-sheet-sub{font-size:14px !important;color:var(--soft) !important;margin-bottom:22px !important;display:block !important;}\\r\\n#st-overlay button.st-btn-danger{\\r\\n  display:block !important;width:100% !important;padding:16px !important;\\r\\n  border-radius:var(--r) !important;background:var(--danger) !important;\\r\\n  color:#fff !important;font-size:15px !important;font-weight:600 !important;\\r\\n  text-align:center !important;margin-bottom:10px !important;\\r\\n  all:unset !important;\\r\\n  display:block !important;width:100% !important;padding:16px !important;\\r\\n  border-radius:var(--r) !important;background:var(--danger) !important;\\r\\n  color:#fff !important;font-size:15px !important;font-weight:600 !important;\\r\\n  text-align:center !important;margin-bottom:10px !important;\\r\\n  cursor:pointer !important;box-sizing:border-box !important;\\r\\n}\\r\\n#st-overlay button.st-btn-cancel-sheet{\\r\\n  all:unset !important;\\r\\n  display:block !important;width:100% !important;padding:14px !important;\\r\\n  border-radius:var(--r) !important;border:1.5px solid var(--line) !important;\\r\\n  color:var(--soft) !important;font-size:15px !important;text-align:center !important;\\r\\n  cursor:pointer !important;box-sizing:border-box !important;\\r\\n}\\r\\n<\\/style>\\r\\n\\r\\n<div id=\\\"st\\\">\\r\\n\\r\\n  <!-- SCREEN: PIN -->\\r\\n  <div class=\\\"st-screen on\\\" id=\\\"st-pin\\\">\\r\\n    <span class=\\\"st-eyebrow\\\">Spiritual Touch<\\/span>\\r\\n    <span class=\\\"st-h1\\\">Team-Kalender<\\/span>\\r\\n    <span class=\\\"st-lead\\\">Gib Deinen pers\\u00f6nlichen Code ein<\\/span>\\r\\n    <div class=\\\"st-dots\\\">\\r\\n      <div class=\\\"st-dot\\\" id=\\\"sd0\\\"><\\/div>\\r\\n      <div class=\\\"st-dot\\\" id=\\\"sd1\\\"><\\/div>\\r\\n      <div class=\\\"st-dot\\\" id=\\\"sd2\\\"><\\/div>\\r\\n      <div class=\\\"st-dot\\\" id=\\\"sd3\\\"><\\/div>\\r\\n    <\\/div>\\r\\n    <div class=\\\"st-keypad\\\">\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'1\')\\\">1<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'2\')\\\">2<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'3\')\\\">3<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'4\')\\\">4<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'5\')\\\">5<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'6\')\\\">6<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'7\')\\\">7<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'8\')\\\">8<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'9\')\\\">9<\\/button>\\r\\n      <button class=\\\"st-key st-key-ghost\\\" onclick=\\\"stClear()\\\">Leer<\\/button>\\r\\n      <button class=\\\"st-key\\\" onclick=\\\"stPress(\'0\')\\\">0<\\/button>\\r\\n      <button class=\\\"st-key st-key-ghost\\\" onclick=\\\"stDel()\\\">\\u232b<\\/button>\\r\\n    <\\/div>\\r\\n    <div class=\\\"st-pin-err\\\" id=\\\"st-pin-err\\\"><\\/div>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- SCREEN: LIST -->\\r\\n  <div class=\\\"st-screen\\\" id=\\\"st-list\\\">\\r\\n    <div class=\\\"st-topbar\\\">\\r\\n      <div class=\\\"st-hello\\\" id=\\\"st-hello\\\">Hallo<\\/div>\\r\\n      <button class=\\\"st-logout\\\" onclick=\\\"stLogout()\\\">abmelden<\\/button>\\r\\n    <\\/div>\\r\\n    <span class=\\\"st-section\\\">Deine Verf\\u00fcgbarkeiten<\\/span>\\r\\n    <div id=\\\"st-entries\\\"><\\/div>\\r\\n    <button class=\\\"st-add\\\" onclick=\\\"stOpenForm(null)\\\">+ Verf\\u00fcgbarkeit hinzuf\\u00fcgen<\\/button>\\r\\n  <\\/div>\\r\\n\\r\\n  <!-- SCREEN: FORM -->\\r\\n  <div class=\\\"st-screen\\\" id=\\\"st-form\\\">\\r\\n    <button class=\\\"st-back\\\" onclick=\\\"stGo(\'list\')\\\">\\u2190 Zur\\u00fcck<\\/button>\\r\\n    <span class=\\\"st-h1\\\" id=\\\"st-form-title\\\" style=\\\"font-size:22px !important;margin-bottom:22px !important;\\\">Verf\\u00fcgbarkeit hinzuf\\u00fcgen<\\/span>\\r\\n\\r\\n    <div class=\\\"st-warn\\\" id=\\\"st-warn\\\">\\r\\n      <span class=\\\"st-warn-ico\\\">\\u26a0\\ufe0f<\\/span>\\r\\n      <div class=\\\"st-warn-txt\\\">\\r\\n        <b>Du hast an diesem Tag schon einen Eintrag:<\\/b>\\r\\n        <span class=\\\"st-warn-sub\\\" id=\\\"st-warn-sub\\\"><\\/span>\\r\\n        Du kannst trotzdem speichern \\u2014 der alte Eintrag bleibt.\\r\\n      <\\/div>\\r\\n    <\\/div>\\r\\n    <div class=\\\"st-err\\\" id=\\\"st-err\\\">\\r\\n      <span class=\\\"st-err-ico\\\">\\ud83d\\udeab<\\/span>\\r\\n      <div class=\\\"st-err-txt\\\"><b>Endzeit liegt vor Startzeit<\\/b> \\u2014 bitte korrigieren.<\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <div class=\\\"st-field\\\">\\r\\n      <label>Datum<\\/label>\\r\\n      <input type=\\\"date\\\" id=\\\"st-date\\\" class=\\\"st-input\\\" onchange=\\\"stCheckDate()\\\">\\r\\n    <\\/div>\\r\\n    <div class=\\\"st-row\\\">\\r\\n      <div class=\\\"st-field\\\">\\r\\n        <label>Von<\\/label>\\r\\n        <input type=\\\"time\\\" id=\\\"st-from\\\" class=\\\"st-input\\\" value=\\\"09:00\\\" onchange=\\\"stCheckTimes()\\\">\\r\\n      <\\/div>\\r\\n      <div class=\\\"st-field\\\">\\r\\n        <label>Bis<\\/label>\\r\\n        <input type=\\\"time\\\" id=\\\"st-to\\\" class=\\\"st-input\\\" value=\\\"18:00\\\" onchange=\\\"stCheckTimes()\\\">\\r\\n      <\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <button class=\\\"st-save\\\" id=\\\"st-save\\\" onclick=\\\"stSave()\\\">Speichern<\\/button>\\r\\n    <button class=\\\"st-cancel\\\" onclick=\\\"stGo(\'list\')\\\">Abbrechen<\\/button>\\r\\n  <\\/div>\\r\\n\\r\\n<\\/div>\\r\\n\\r\\n<!-- DELETE OVERLAY (au\\u00dferhalb #st f\\u00fcr position:fixed) -->\\r\\n<div class=\\\"st-overlay\\\" id=\\\"st-overlay\\\">\\r\\n  <div class=\\\"st-sheet\\\">\\r\\n    <span class=\\\"st-sheet-title\\\">Eintrag l\\u00f6schen?<\\/span>\\r\\n    <span class=\\\"st-sheet-sub\\\" id=\\\"st-del-sub\\\"><\\/span>\\r\\n    <button class=\\\"st-btn-danger\\\" onclick=\\\"stConfirmDel()\\\">Ja, l\\u00f6schen<\\/button>\\r\\n    <button class=\\\"st-btn-cancel-sheet\\\" onclick=\\\"stCloseOverlay()\\\">Abbrechen<\\/button>\\r\\n  <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<script>\\r\\nconst ST_USERS={\'1234\':\'Jen\',\'5678\':\'Eva\'};\\r\\nlet stUser=null,stEditId=null,stDelId=null,stPin=\'\',stTimeErr=false,stNextId=4;\\r\\nlet stEntries=[\\r\\n  {id:1,date:\'2026-07-06\',from:\'09:30\',to:\'18:30\'},\\r\\n  {id:2,date:\'2026-07-08\',from:\'09:30\',to:\'16:00\'},\\r\\n  {id:3,date:\'2026-07-10\',from:\'09:30\',to:\'15:00\'}\\r\\n];\\r\\n\\r\\nfunction stGo(n){\\r\\n  document.querySelectorAll(\'.st-screen\').forEach(s=>s.classList.remove(\'on\'));\\r\\n  document.getElementById(\'st-\'+n).classList.add(\'on\');\\r\\n  document.getElementById(\'st\').scrollIntoView({behavior:\'smooth\',block:\'start\'});\\r\\n}\\r\\nfunction stPress(n){\\r\\n  if(stPin.length>=4)return;\\r\\n  stPin+=n;stRenderDots();\\r\\n  if(stPin.length===4)setTimeout(stTryLogin,220);\\r\\n}\\r\\nfunction stDel(){stPin=stPin.slice(0,-1);stRenderDots();}\\r\\nfunction stClear(){stPin=\'\';stRenderDots();}\\r\\nfunction stRenderDots(){\\r\\n  for(let i=0;i<4;i++)\\r\\n    document.getElementById(\'sd\'+i).classList.toggle(\'on\',i<stPin.length);\\r\\n}\\r\\nfunction stTryLogin(){\\r\\n  if(ST_USERS[stPin]){\\r\\n    stUser=ST_USERS[stPin];\\r\\n    document.getElementById(\'st-hello\').textContent=\'Hallo \'+stUser;\\r\\n    document.getElementById(\'st-pin-err\').textContent=\'\';\\r\\n    document.querySelectorAll(\'.st-dot\').forEach(d=>d.classList.remove(\'err\'));\\r\\n    stRenderList();stGo(\'list\');\\r\\n  } else {\\r\\n    document.getElementById(\'st-pin-err\').textContent=\'Falscher Code \\u2014 bitte nochmal versuchen\';\\r\\n    document.querySelectorAll(\'.st-dot\').forEach(d=>d.classList.add(\'err\'));\\r\\n    setTimeout(()=>{stPin=\'\';stRenderDots();document.querySelectorAll(\'.st-dot\').forEach(d=>d.classList.remove(\'err\'));},700);\\r\\n  }\\r\\n}\\r\\nfunction stLogout(){stUser=null;stPin=\'\';stRenderDots();stGo(\'pin\');}\\r\\nfunction stRenderList(){\\r\\n  const el=document.getElementById(\'st-entries\');\\r\\n  if(!stEntries.length){el.innerHTML=\'<div class=\\\"st-empty\\\">Noch keine Eintr\\u00e4ge<\\/div>\';return;}\\r\\n  const s=[...stEntries].sort((a,b)=>a.date.localeCompare(b.date));\\r\\n  el.innerHTML=s.map(e=>`\\r\\n    <div class=\\\"st-card\\\">\\r\\n      <span class=\\\"st-card-date\\\">${stFmt(e.date)}<\\/span>\\r\\n      <span class=\\\"st-card-time\\\">${e.from} \\u2013 ${e.to} Uhr<\\/span>\\r\\n      <span class=\\\"st-card-bar\\\"><\\/span>\\r\\n      <div class=\\\"st-card-act\\\">\\r\\n        <button class=\\\"st-edit\\\" onclick=\\\"stOpenForm(${e.id})\\\">\\u00c4ndern<\\/button>\\r\\n        <button class=\\\"st-del\\\" onclick=\\\"stOpenDel(${e.id})\\\">L\\u00f6schen<\\/button>\\r\\n      <\\/div>\\r\\n    <\\/div>`).join(\'\');\\r\\n}\\r\\nfunction stFmt(iso){\\r\\n  const d=new Date(iso+\'T12:00:00\');\\r\\n  return d.toLocaleDateString(\'de-DE\',{weekday:\'short\',day:\'numeric\',month:\'long\'});\\r\\n}\\r\\nfunction stOpenForm(id){\\r\\n  stEditId=id;\\r\\n  document.getElementById(\'st-warn\').classList.remove(\'on\');\\r\\n  document.getElementById(\'st-err\').classList.remove(\'on\');\\r\\n  document.getElementById(\'st-save\').disabled=false;stTimeErr=false;\\r\\n  if(id){\\r\\n    const e=stEntries.find(x=>x.id===id);\\r\\n    document.getElementById(\'st-form-title\').textContent=\'Verf\\u00fcgbarkeit \\u00e4ndern\';\\r\\n    document.getElementById(\'st-date\').value=e.date;\\r\\n    document.getElementById(\'st-from\').value=e.from;\\r\\n    document.getElementById(\'st-to\').value=e.to;\\r\\n  } else {\\r\\n    document.getElementById(\'st-form-title\').textContent=\'Verf\\u00fcgbarkeit hinzuf\\u00fcgen\';\\r\\n    const t=new Date();t.setDate(t.getDate()+1);\\r\\n    document.getElementById(\'st-date\').value=t.toISOString().split(\'T\')[0];\\r\\n    document.getElementById(\'st-from\').value=\'09:00\';\\r\\n    document.getElementById(\'st-to\').value=\'18:00\';\\r\\n  }\\r\\n  stCheckDate();stGo(\'form\');\\r\\n}\\r\\nfunction stCheckDate(){\\r\\n  const date=document.getElementById(\'st-date\').value;if(!date)return;\\r\\n  const clash=stEntries.find(e=>e.date===date&&e.id!==stEditId);\\r\\n  if(clash){\\r\\n    document.getElementById(\'st-warn-sub\').textContent=stFmt(clash.date)+\', \'+clash.from+\' \\u2013 \'+clash.to+\' Uhr\';\\r\\n    document.getElementById(\'st-warn\').classList.add(\'on\');\\r\\n  } else {document.getElementById(\'st-warn\').classList.remove(\'on\');}\\r\\n}\\r\\nfunction stCheckTimes(){\\r\\n  const f=document.getElementById(\'st-from\').value;\\r\\n  const t=document.getElementById(\'st-to\').value;\\r\\n  stTimeErr=!!(f&&t&&t<=f);\\r\\n  document.getElementById(\'st-err\').classList.toggle(\'on\',stTimeErr);\\r\\n  document.getElementById(\'st-save\').disabled=stTimeErr;\\r\\n}\\r\\nfunction stSave(){\\r\\n  if(stTimeErr)return;\\r\\n  const date=document.getElementById(\'st-date\').value;\\r\\n  const from=document.getElementById(\'st-from\').value;\\r\\n  const to=document.getElementById(\'st-to\').value;\\r\\n  if(!date||!from||!to)return;\\r\\n  if(stEditId){const e=stEntries.find(x=>x.id===stEditId);e.date=date;e.from=from;e.to=to;}\\r\\n  else{stEntries.push({id:stNextId++,date,from,to});}\\r\\n  stRenderList();stGo(\'list\');\\r\\n}\\r\\nfunction stOpenDel(id){\\r\\n  stDelId=id;const e=stEntries.find(x=>x.id===id);\\r\\n  document.getElementById(\'st-del-sub\').textContent=stFmt(e.date)+\', \'+e.from+\' \\u2013 \'+e.to+\' Uhr\';\\r\\n  document.getElementById(\'st-overlay\').classList.add(\'on\');\\r\\n}\\r\\nfunction stCloseOverlay(){stDelId=null;document.getElementById(\'st-overlay\').classList.remove(\'on\');}\\r\\nfunction stConfirmDel(){stEntries=stEntries.filter(x=>x.id!==stDelId);stCloseOverlay();stRenderList();}\\r\\n<\\/script>\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\\t\\t<\\/div>\\n\\t\\t\",\"scripts\":[],\"styles\":[]}}'),(140606,18724,'_elementor_element_cache','{\"timeout\":1785587812,\"value\":{\"content\":\"<div class=\\\"elementor-element elementor-element-153b774 e-flex e-con-boxed e-con e-parent\\\" data-id=\\\"153b774\\\" data-element_type=\\\"container\\\" data-e-type=\\\"container\\\">\\n\\t\\t\\t\\t\\t<div class=\\\"e-con-inner\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-element elementor-element-60d4f71 elementor-widget elementor-widget-spacer\\\" data-id=\\\"60d4f71\\\" data-element_type=\\\"widget\\\" data-e-type=\\\"widget\\\" data-widget_type=\\\"spacer.default\\\">\\n\\t\\t\\t\\t<div class=\\\"elementor-widget-container\\\">\\n\\t\\t\\t\\t\\t\\t\\t<div class=\\\"elem