# Table: `txva_postmeta`
# Approximate rows expected in table: 14256
/*!40103 SET @OLD_TIME_ZONE=@@TIME_ZONE */;

DROP TABLE IF EXISTS `txva_postmeta`;

CREATE TABLE `txva_postmeta` (
  `meta_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `post_id` bigint(20) unsigned NOT NULL DEFAULT 0,
  `meta_key` varchar(255) DEFAULT NULL,
  `meta_value` longtext DEFAULT NULL,
  PRIMARY KEY (`meta_id`),
  KEY `post_id` (`post_id`),
  KEY `meta_key` (`meta_key`(191))
) ENGINE=InnoDB AUTO_INCREMENT=141440 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

